import React, { useState, useEffect } from 'react';
import axios from 'axios';
import {
    Chart as ChartJS,
    CategoryScale,
    LinearScale,
    BarElement,
    Title,
    Tooltip,
    Legend,
} from 'chart.js';
import { Bar } from 'react-chartjs-2';

// Registrasi komponen Chart.js
ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

const Hitung = () => {
    const [ranking, setRanking] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');

    useEffect(() => {
        const fetchRanking = async () => {
            try {
                const response = await axios.get('http://127.0.0.1:5000/calculate');
                setRanking(response.data);
            } catch (err) {
                setError('Error fetching ranking data');
            } finally {
                setLoading(false);
            }
        };

        fetchRanking();
    }, []);

    const chartData = {
        labels: ranking.map((item) => item.name),
        datasets: [
            {
                label: 'Skor Alternatif',
                data: ranking.map((item) => item.score),
                backgroundColor: 'rgba(75, 151, 192, 0.6)',
                borderColor: 'rgb(104, 75, 192)',
                borderWidth: 1,
            },
        ],
    };

    const chartOptions = {
        responsive: true,
        plugins: {
            legend: {
                position: 'top',
            },
        },
        scales: {
            y: {
                beginAtZero: true,
                title: {
                    display: true,
                    text: 'Skor',
                },
            },
            x: {
                title: {
                    display: true,
                    text: 'Alternatif',
                },
            },
        },
    };

    return (
        <div className="container">
            <h1 className="mt-4">Hasil Perhitungan AHP</h1>
            {loading && <p>Loading...</p>}
            {error && <p style={{ color: 'red' }}>{error}</p>}
            {!loading && !error && (
                <>
                    <table className="table table-bordered table-hover">
                        <thead>
                            <tr>
                                <th>No.</th>
                                <th>ID Alternatif</th>
                                <th>Nama Alternatif</th>
                                <th>Skor</th>
                            </tr>
                        </thead>
                        <tbody>
                            {ranking.map((item, index) => (
                                <tr key={item.id}>
                                    <td>{index + 1}</td>
                                    <td>{item.id}</td>
                                    <td>{item.name}</td>
                                    <td>{item.score.toFixed(4)}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>

                    <h2 className="mt-4">Grafik Perangkingan</h2>
                    <Bar key={JSON.stringify(chartData)} data={chartData} options={chartOptions} />
                </>
            )}
        </div>
    );
};

export default Hitung;
